class Solution:
    def getMaximumXor(self, nums: List[int], maximumBit: int) -> List[int]:
        result = [0]*len(nums)
        mask = 2**maximumBit-1
        for i in range(len(nums)):
            mask ^= nums[i]
            result[-1-i] = mask
        return result

